from scipy.optimize import least_squares
def fit(fn,p0):
    best=None
    for s in range(30):
        p=np.random.RandomState(s).randn(len(p0))*1.0+np.array(p0)
        try:
            r=least_squares(lambda p: fn(p)-dA_dt,p,max_nfev=3000)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    return best.cost*2/np.sum((dA_dt-dA_dt.mean())**2), np.round(best.x,4)
